head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name     : SMK Darut Taqwa - Landing
Designer : Custom
Version  : 1.0
-----------------------------------------------
*/

/* Variable definitions
====================
<Variable name="keycolor" description="Warna Utama" type="color" default="#3b82f6" value="#3b82f6"/>
<Variable name="primary.color" description="Warna Primer" type="color" default="#2563eb" value="#2563eb"/>
<Variable name="secondary.color" description="Warna Sekunder" type="color" default="#7c3aed" value="#7c3aed"/>
<Variable name="accent.color" description="Warna Aksen" type="color" default="#db2777" value="#db2777"/>
<Variable name="body.background.color" description="Warna Latar" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="text.color" description="Warna Teks" type="color" default="#1e293b" value="#1e293b"/>
*/

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  background-color: $(body.background.color);
  color: $(text.color);
}

/* Sembunyikan navbar bawaan Blogger */
#navbar, #navbar-iframe {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
}

/* Soft Blurred Shapes Background */
.blob {
  position: absolute;
  width: 500px;
  height: 500px;
  background: linear-gradient(135deg, #dbeafe 0%, #ede9fe 100%);
  filter: blur(80px);
  border-radius: 50%;
  z-index: -1;
  opacity: 0.6;
}

.glass-card {
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.8);
  box-shadow: 0 8px 32px rgba(31, 38, 135, 0.07);
}

.gradient-text {
  background: linear-gradient(to right, $(primary.color), $(secondary.color), $(accent.color));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.btn-gradient {
  background: linear-gradient(to right, $(primary.color), $(secondary.color));
  transition: all 0.3s ease;
}
.btn-gradient:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 20px rgba(99, 102, 241, 0.3);
}

/* Potong isi postingan di halaman daftar */
.post-excerpt {
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.post-excerpt img {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
}

/* Konten postingan tunggal */
.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
  margin: 1.5rem 0;
}
.post-body a { color: $(primary.color); text-decoration: underline; }
.post-body h2, .post-body h3 { font-weight: 800; margin: 1.5rem 0 0.75rem; }
.post-body ul, .post-body ol { margin-left: 1.25rem; list-style: disc; }
.post-body blockquote {
  border-left: 4px solid $(primary.color);
  padding-left: 1rem;
  font-style: italic;
  color: #64748b;
}
